def can_make_palindrome_queries(s, queries):
 prefix=[0]
 for char in s:prefix.append(prefix[-1]^(1<<(ord(char)-97)))
 return [((prefix[right+1]^prefix[left]).bit_count()//2)<=k for left,right,k in queries]

